import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const EVIDENCE_TYPES = ['통장', '카드', '현금영수증', '전자세금계산서'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function fail(): never {
  throw new ApiError(400, 'VALIDATION_FAILED', '필수 값이 없거나 형식이 올바르지 않습니다.');
}

function requiredId(value: unknown): string {
  if (value === undefined || value === null || value === '') {
    fail();
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    fail();
  }
  return String(n);
}

function optionalId(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return requiredId(value);
}

@Controller('api/v1')
export class FnSfr00402Controller {
  @Post('/expense-resolutions')
  @HttpCode(200)
  async createExpenseResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const resolutionDate = data['resolutionDate'];
    if (typeof resolutionDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(resolutionDate)) {
      fail();
    }
    const projectId = requiredId(data['projectId']);
    const budgetItemId = requiredId(data['budgetItemId']);
    const departmentId = requiredId(data['departmentId']);
    const purchaseRequestId = optionalId(data['purchaseRequestId']);
    const partnerId = optionalId(data['partnerId']);
    const rawAmount = data['amount'];
    if (rawAmount === undefined || rawAmount === null || rawAmount === '') {
      fail();
    }
    const amountNum = Number(rawAmount);
    if (!Number.isFinite(amountNum) || amountNum <= 0) {
      fail();
    }
    const evidenceType = data['evidenceType'];
    if (typeof evidenceType !== 'string' || !EVIDENCE_TYPES.includes(evidenceType)) {
      fail();
    }
    return transaction(async (db) => {
      const project = await db.query('SELECT project_id FROM project WHERE project_id = CAST(:id AS bigint)', { id: projectId });
      if (project.length === 0) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      const item = await db.query('SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:id AS bigint)', { id: budgetItemId });
      if (item.length === 0) {
        throw new ApiError(404, 'BUDGET_ITEM_NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const dept = await db.query('SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)', { id: departmentId });
      if (dept.length === 0) {
        throw new ApiError(404, 'DEPARTMENT_NOT_FOUND', '결의부서를 찾을 수 없습니다.');
      }
      if (partnerId !== null) {
        const partner = await db.query('SELECT partner_id FROM partner WHERE partner_id = CAST(:id AS bigint)', { id: partnerId });
        if (partner.length === 0) {
          throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처를 찾을 수 없습니다.');
        }
      }
      if (purchaseRequestId !== null) {
        const pr = await db.query(
          'SELECT CAST(amount AS float8) AS "amount" FROM purchase_request WHERE purchase_request_id = CAST(:id AS bigint)',
          { id: purchaseRequestId },
        );
        if (pr.length === 0) {
          throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '연결 품의서를 찾을 수 없습니다.');
        }
        // 가정: 품의서 한 건당 결의 금액 한 건이 품의 금액을 넘지 않는지만 검사한다.
        if (amountNum > Number(pr[0]['amount'])) {
          throw new ApiError(422, 'AMOUNT_EXCEEDS_PURCHASE_REQUEST', '결의 금액이 연결 품의 금액을 초과합니다.');
        }
      }
      const rows = await db.query(
        'INSERT INTO expense_resolution ('
          + ' resolution_date, department_id, author_id, resolution_type, project_id, budget_item_id,'
          + ' partner_id, purchase_request_id, amount, evidence_type, approval_status, created_at, updated_at'
          + ') VALUES ('
          + ' CAST(:resolutionDate AS date), CAST(:departmentId AS bigint), CAST(:userId AS bigint), \'지출\','
          + ' CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint), CAST(:partnerId AS bigint),'
          + ' CAST(:purchaseRequestId AS bigint), CAST(:amount AS numeric), :evidenceType, \'기안\', now(), now()'
          + ') RETURNING expense_resolution_id AS "expenseResolutionId"',
        {
          resolutionDate,
          departmentId,
          userId: user.id,
          projectId,
          budgetItemId,
          partnerId,
          purchaseRequestId,
          amount: String(amountNum),
          evidenceType,
        },
      );
      const id = rows[0]['expenseResolutionId'];
      // 자동 번호: ER-날짜-일련번호
      await db.execute(
        'UPDATE expense_resolution'
          + ' SET document_no = \'ER-\' || to_char(now(), \'YYYYMMDD\') || \'-\' || lpad(CAST(expense_resolution_id AS text), 6, \'0\')'
          + ' WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id: String(id) },
      );
      const out = await db.query(
        'SELECT expense_resolution_id AS "expenseResolutionId", document_no AS "documentNo", approval_status AS "approvalStatus"'
          + ' FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id: String(id) },
      );
      return out[0];
    });
  }

  @Get('/expense-resolutions')
  async listExpenseResolutions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const pageNum = Number(query['page'] ?? 0);
    let size = Number(query['size'] ?? DEFAULT_SIZE);
    if (!Number.isInteger(pageNum) || pageNum < 0 || !Number.isInteger(size) || size < 1) {
      fail();
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const projectId = optionalId(query['projectId']);
    const statusRaw = query['approvalStatus'];
    const approvalStatus = typeof statusRaw === 'string' && statusRaw !== '' ? statusRaw : null;
    return transaction(async (db) => {
      const params = { projectId, approvalStatus, limit: size, offset: pageNum * size };
      const items = await db.query(
        'SELECT expense_resolution_id AS "expenseResolutionId", document_no AS "documentNo",'
          + ' resolution_date AS "resolutionDate", CAST(amount AS float8) AS "amount",'
          + ' approval_status AS "approvalStatus"'
          + ' FROM expense_resolution'
          + ' WHERE (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))'
          + ' AND (CAST(:approvalStatus AS text) IS NULL OR approval_status = CAST(:approvalStatus AS text))'
          + ' ORDER BY expense_resolution_id DESC'
          + ' LIMIT CAST(:limit AS int) OFFSET CAST(:offset AS int)',
        params,
      );
      const counts = await db.query(
        'SELECT CAST(COUNT(*) AS int) AS "total" FROM expense_resolution'
          + ' WHERE (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))'
          + ' AND (CAST(:approvalStatus AS text) IS NULL OR approval_status = CAST(:approvalStatus AS text))',
        { projectId, approvalStatus },
      );
      return { items, page: pageNum, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/expense-resolutions/:expenseResolutionId/submit')
  @HttpCode(200)
  async submitExpenseResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['expenseResolutionId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '결의서를 찾을 수 없습니다.');
    }
    checks.inputOf(req.body);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT expense_resolution_id AS "id", approval_status AS "approvalStatus", department_id AS "departmentId", document_no AS "documentNo"'
          + ' FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '결의서를 찾을 수 없습니다.');
      }
      if (rows[0]['approvalStatus'] !== '기안') {
        throw new ApiError(409, 'EXPENSE_RESOLUTION_STATUS_CONFLICT', '상신할 수 있는 상태가 아닙니다.');
      }
      // 가정: 연계 결재가 켜진 사용 중 양식 중 첫 번째를 결의서 양식으로 쓴다.
      const forms = await db.query(
        'SELECT approval_form_id AS "formId" FROM approval_form'
          + ' WHERE use_status = \'사용\' AND is_linked_approval = true'
          + ' ORDER BY approval_form_id LIMIT 1',
        {},
      );
      if (forms.length === 0) {
        throw new ApiError(502, 'APPROVAL_LINKAGE_FAILED', '전자결재 연계에 실패했습니다.');
      }
      const docs = await db.query(
        'INSERT INTO approval_document ('
          + ' approval_form_id, drafter_id, drafter_department_id, document_number, title,'
          + ' approval_status, is_urgent, is_secret, linked_business_type, linked_business_id,'
          + ' submitted_at, created_at, updated_at'
          + ') SELECT CAST(:formId AS bigint), CAST(:userId AS bigint), department_id, document_no,'
          + ' \'지출결의서 \' || document_no, \'결재대기\', false, false, \'expense_resolution\', expense_resolution_id,'
          + ' now(), now(), now()'
          + ' FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint)'
          + ' RETURNING approval_document_id AS "approvalDocumentId"',
        { formId: String(forms[0]['formId']), userId: user.id, id },
      );
      if (docs.length === 0) {
        throw new ApiError(502, 'APPROVAL_LINKAGE_FAILED', '전자결재 연계에 실패했습니다.');
      }
      await db.execute(
        'UPDATE expense_resolution SET approval_status = \'결재대기\','
          + ' approval_document_id = CAST(:docId AS bigint), updated_at = now()'
          + ' WHERE expense_resolution_id = CAST(:id AS bigint)',
        { docId: String(docs[0]['approvalDocumentId']), id },
      );
      return { approvalStatus: '결재대기' };
    });
  }
}

