import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUSES: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const EVIDENCES: [string, string][] = [
  ['통장', '통장'],
  ['카드', '카드'],
  ['현금영수증', '현금영수증'],
  ['전자세금계산서', '전자세금계산서'],
];

export default function FnSfr00402Page({ role, notify }: PageProps) {
  const [pageNo, setPageNo] = useState(0);
  const [projectDraft, setProjectDraft] = useState<number | string>('');
  const [statusDraft, setStatusDraft] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [submitTarget, setSubmitTarget] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({});
  const [budgetProject, setBudgetProject] = useState<number | string>('');

  const list = useData<Page>(
    () => call<Page>('GET', '/expense-resolutions', role, undefined, { ...applied, page: pageNo, size: 20 }),
    [applied, pageNo],
  );
  const budgets = useData<Page>(
    () => {
      if (budgetProject === '') {
        return Promise.resolve({ items: [], page: 0, size: 20, total: 0 } as Page);
      }
      return call<Page>('GET', '/budget-statuses', role, undefined, { projectId: budgetProject, size: 200 });
    },
    [budgetProject],
  );

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const draftCount = rows.filter((r) => r['approvalStatus'] === '기안').length;
  const sumAmount = rows.reduce((acc, r) => acc + Number(r['amount'] || 0), 0);

  function set(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function search() {
    setPageNo(0);
    setApplied({ projectId: projectDraft, approvalStatus: statusDraft });
  }

  function reset() {
    setProjectDraft('');
    setStatusDraft('');
    setPageNo(0);
    setApplied({});
  }

  async function create() {
    if (
      !form['resolutionDate'] ||
      !form['projectId'] ||
      !form['budgetItemId'] ||
      form['amount'] === undefined ||
      form['amount'] === '' ||
      !form['evidenceType'] ||
      !form['departmentId']
    ) {
      throw new Error('필수 항목을 모두 입력해 주세요.');
    }
    await call('POST', '/expense-resolutions', role, form);
    notify('결의서를 등록했습니다.');
    setCreating(false);
    setForm({});
    list.reload();
  }

  async function submitDoc() {
    if (!submitTarget) {
      return;
    }
    const id = submitTarget['expenseResolutionId'];
    await call('POST', `/expense-resolutions/${id}/submit`, role, {});
    notify('결재를 상신했습니다.');
    setSubmitTarget(null);
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 결의</h2>
        <Num value={total} />
      </section>
      <section className="box span-4">
        <h2>상신 대기</h2>
        <Num value={draftCount} />
      </section>
      <section className="box span-4">
        <h2>현재 쪽 결의 금액</h2>
        <Num value={sumAmount} />
      </section>

      <section className="box span-8">
        <h2>결의 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectDraft} onChange={setProjectDraft} />
          </Field>
          <Field label="결재 상태">
            <Select value={statusDraft} onChange={setStatusDraft} options={STATUSES} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={() => { setForm({}); setCreating(true); }}>
            결의서 등록
          </button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={rows}
          onRowClick={(row) => setDetail(row)}
          empty="결의서가 없습니다."
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'resolutionDate', label: '결의일자', render: (r) => <DateText value={r['resolutionDate']} /> },
            { key: 'amount', label: '결의 금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['approvalStatus'] === '기안' ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      setSubmitTarget(r);
                    }}
                  >
                    상신
                  </button>
                ) : null,
            },
          ]}
        />
        <Pager page={pageNo} size={20} total={total} onPage={setPageNo} />
      </section>

      <section className="box span-4">
        <h2>예산 현황</h2>
        <Field label="프로젝트">
          <LookupSelect table="project" role={role} value={budgetProject} onChange={setBudgetProject} />
        </Field>
        {budgets.error ? <ErrorText text={budgets.error} /> : null}
        <DataTable
          rows={budgets.data ? budgets.data.items : []}
          empty="프로젝트를 고르면 예산 현황이 보입니다."
          columns={[
            { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table="budget_item" role={role} value={r['budgetItemId']} /> },
            { key: 'execBudgetAmount', label: '실행예산액', render: (r) => <Num value={r['execBudgetAmount']} /> },
            { key: 'carryoverAmount', label: '이월예산액', render: (r) => <Num value={r['carryoverAmount']} /> },
            { key: 'totalBudgetAmount', label: '예산총액', render: (r) => <Num value={r['totalBudgetAmount']} /> },
            { key: 'executedAmount', label: '집행액', render: (r) => <Num value={r['executedAmount']} /> },
            { key: 'balanceAmount', label: '예산잔액', render: (r) => <Num value={r['balanceAmount']} /> },
          ]}
        />
      </section>

      {detail ? (
        <Drawer title="결의서 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['문서번호', String(detail['documentNo'] ?? '')],
              ['결의일자', <DateText value={detail['resolutionDate']} />],
              ['결의 금액', <Num value={detail['amount']} />],
              ['결재 상태', <Badge value={detail['approvalStatus']} />],
            ]}
          />
        </Drawer>
      ) : null}

      {creating ? (
        <Drawer title="결의서 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="저장">
            <Field label="결의일자" required>
              <DateInput value={form['resolutionDate']} onChange={(v) => set('resolutionDate', v)} />
            </Field>
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={form['projectId']} onChange={(v) => set('projectId', v)} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect table="budget_item" role={role} value={form['budgetItemId']} onChange={(v) => set('budgetItemId', v)} />
            </Field>
            <Field label="결의 금액" required>
              <NumberInput value={form['amount']} onChange={(v) => set('amount', v)} />
            </Field>
            <Field label="증빙 유형" required>
              <Select value={form['evidenceType']} onChange={(v) => set('evidenceType', v)} options={EVIDENCES} />
            </Field>
            <Field label="결의부서" required>
              <LookupSelect table="department" role={role} value={form['departmentId']} onChange={(v) => set('departmentId', v)} />
            </Field>
            <Field label="연결 품의서">
              <LookupSelect table="purchase_request" role={role} value={form['purchaseRequestId']} onChange={(v) => set('purchaseRequestId', v)} />
            </Field>
            <Field label="거래처">
              <LookupSelect table="partner" role={role} value={form['partnerId']} onChange={(v) => set('partnerId', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {submitTarget ? (
        <Drawer title="결재 상신" onClose={() => setSubmitTarget(null)}>
          <Form onSubmit={submitDoc} submit="상신" note="이 결의서를 전자결재로 상신합니다.">
            <Pairs
              items={[
                ['문서번호', String(submitTarget['documentNo'] ?? '')],
                ['결의 금액', <Num value={submitTarget['amount']} />],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
